INSERT INTO periods (period_id, period_name, start_year, end_year) VALUES
 ('PER_CARIAN','Carian Civic Polytheism (Hekatomnid–Hellenistic Caria)',-600,-31)
INSERT INTO sources (source_id, source_type, title, scope) VALUES
 ('SRC_LAUMONIER_CARIE','secondary scholarship','Alfred Laumonier, Les cultes indigènes en Carie (Bibliothèque des Écoles françaises d''Athènes et de Rome 188, Paris, 1958)','Foundational monograph on the indigenous and civic cults of Caria: Zeus Labraundos, Zeus Osogo/Zenoposeidon, Zeus of Panamara/Stratios, Hecate of Lagina, the god of Sinuri.')
INSERT INTO _e VALUES
 ('ENT_CAR_PANTHEON','Carian Pantheon','collective','pantheon','Carian','regional polytheism;Anatolian civic cult','B','Hub collective for the indigenous civic deities of Caria attested at the major rural sanctuaries (Labranda, Lagina, Mylasa, Panamara, Sinuri); Laumonier 1958.'),
 ('ENT_CAR_ZEUS_LABRAUNDOS','Zeus Labraundos','deity','sky god','Carian','sky;sovereignty;war;double-axe (labrys)','B','The double-axe-wielding Zeus of the great sanctuary at Labranda near Mylasa, indigenous Carian storm/war god interpreted as Zeus; epigraphically Zeus Labraundos/Labrayndos, his priest the Hekatomnids'' dynastic cult (Mausolus, Idrieus). Laumonier 1958, pp. 37-101.'),
 ('ENT_CAR_ZEUS_OSOGO','Zeus Osogo (Zenoposeidon)','deity','sky god','Carian','sky;sea;fresh water','B','Carian god of Mylasa worshipped as Zeus Osogo / Osogoa, also called Zenoposeidon (Zeus-Poseidon); his temple held a saltwater spring and the trident appeared with the eagle, fusing Zeus and Poseidon. Laumonier 1958, pp. 102-145.'),
 ('ENT_CAR_ZEUS_PANAMAROS','Zeus Panamaros (Zeus Stratios)','deity','sky god','Carian','sky;war;civic protection','B','Zeus of the federal sanctuary at Panamara near Stratonikeia, also titled Zeus Stratios (''of the army''); patron of the Panamareia festival and famed epiphany that repelled a siege. Laumonier 1958, pp. 221-343.'),
 ('ENT_CAR_HECATE_LAGINA','Hecate of Lagina','deity','goddess;chthonic','Carian','liminality;mysteries;civic protection;sovereignty','B','The great Carian Hecate venerated at the sanctuary of Lagina near Stratonikeia, with her annual Kleidos Pompe (procession of the key) and mysteries; a major civic cult equating the indigenous goddess with Greek Hecate. Laumonier 1958, pp. 344-425.'),
 ('ENT_CAR_SINURI','God of Sinuri','deity','local god','Carian','local tutelary;oath;sanctuary protection','C','Indigenous Carian deity (Theos Sinuri) of the rural sanctuary of Sinuri near Mylasa, known from the Hekatomnid-era archive and Carian inscriptions; an autochthonous god retaining his native name rather than a Greek interpretatio. Laumonier 1958, pp. 198-220; Sinuri sanctuary archive.');
