INSERT INTO _r VALUES
 ('ENT_CAR_ZEUS_LABRAUNDOS','member_of','ENT_CAR_PANTHEON','high','Zeus Labraundos of Labranda is a core deity of the Carian civic pantheon (Laumonier 1958).'),
 ('ENT_CAR_ZEUS_OSOGO','member_of','ENT_CAR_PANTHEON','high','Zeus Osogo/Zenoposeidon of Mylasa belongs to the Carian pantheon (Laumonier 1958).'),
 ('ENT_CAR_ZEUS_PANAMAROS','member_of','ENT_CAR_PANTHEON','high','Zeus Panamaros/Stratios of the Panamara sanctuary belongs to the Carian pantheon (Laumonier 1958).'),
 ('ENT_CAR_HECATE_LAGINA','member_of','ENT_CAR_PANTHEON','high','Hecate of Lagina is the leading goddess of the Carian civic pantheon (Laumonier 1958).'),
 ('ENT_CAR_SINURI','member_of','ENT_CAR_PANTHEON','high','The god of the Sinuri sanctuary is an indigenous member of the Carian pantheon (Laumonier 1958).'),
 ('ENT_CAR_ZEUS_LABRAUNDOS','cult_form_of','ENT_ZEUS','high','Zeus Labraundos is the Carian cult-form/local epithet of Zeus, the indigenous double-axe god interpreted as Zeus at Labranda.'),
 ('ENT_CAR_ZEUS_OSOGO','cult_form_of','ENT_ZEUS','high','Zeus Osogo of Mylasa is a Carian cult-form of Zeus (the indigenous god worshipped under the name Zeus Osogo).'),
 ('ENT_CAR_ZEUS_PANAMAROS','cult_form_of','ENT_ZEUS','high','Zeus Panamaros/Stratios is the Carian cult-form of Zeus at the Panamara sanctuary.'),
 ('ENT_CAR_HECATE_LAGINA','cult_form_of','ENT_HECATE','high','Hecate of Lagina is the great Carian cult-form of the Greek Hecate, the indigenous goddess venerated as Hecate at Lagina.'),
 ('ENT_CAR_ZEUS_OSOGO','equated_with','ENT_POSEIDON','high','Zeus Osogo bore the title Zenoposeidon and combined attributes (trident with eagle, saltwater spring) of Poseidon, an ancient interpretatio fusing Zeus and Poseidon.');
